using namespace cg3::cgal::internal;

VD vd;
std::vector<Point_2> cgal_points;
cgal_points.reserve(points.size());
for (const auto& p : points) {
    cgal_points.emplace_back(p.x, p.y);
}

vd.insert(cgal_points.begin(), cgal_points.end());

std::vector<std::vector<cg3::Point2d>> result;
result.reserve(points.size());

for (const auto& site : cgal_points) {
    std::vector<cg3::Point2d> cell_vertices;
    Face_handle face = vd.locate_face(site);

    if (face) {
        Ccb_halfedge_circulator hc = vd.ccb(face);
        do {
            Vertex_handle v = hc->vertex();
            if (v) {
                Point_2 p = v->point();
                cell_vertices.emplace_back(cg3::Point2d(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
            }
            hc++;
        } while (hc != vd.ccb(face));
    }
    result.push_back(cell_vertices);
}

return result;

